        "content_ka": "გერმანელებს ხშირად უწოდებენ მოგზაურობის მსოფლიო ჩემპიონებს (Reiseweltmeister). საშუალო სტატისტიკური გერმანელი წელიწადში 30 დღე შვებულებით სარგებლობს."
